use strict;
use warnings;
use ExtUtils::MakeMaker;

WriteMakefile(
    NAME             => 'Config::Tiny::Lite',
    VERSION_FROM     => 'lib/Config/Tiny/Lite.pm',
    MIN_PERL_VERSION => '5.008001',
    PREREQ_PM        => { 'URI' => '1.60' },
    TEST_REQUIRES    => { 'Test::More' => '0.88' },
);

package Config::Tiny::Lite;
use strict;
use warnings;
use URI;

our $VERSION = '0.01';

sub parse {
    my ($class, $text) = @_;
    my @sections = $text =~ /^\[(\w+)\]/mg;
    return \@sections;
}

1;

use strict;
use warnings;
use Test::More;
use Config::Tiny::Lite;

ok(1, 'loads');

done_testing();

use strict;
use warnings;
use Test::More;
use Config::Tiny::Lite;

is_deeply(Config::Tiny::Lite->parse("[a]\n"), ['a'], 'parses one section');
is(scalar @{Config::Tiny::Lite->parse("[a]\n[b]\n")}, 2, 'parses two sections');
is_deeply(Config::Tiny::Lite->parse("[b]\n[a]\n"), ['b', 'a'], 'keeps section order');

done_testing();
